What integer is printed by the following C program?
```c
#include <stdio.h>
int fun(int n) {
    static int d = 1;
    if (n <= 1) return d;
    d += n;
    return fun(n - 1) + d;
}
int main() {
    printf("%d", fun(3));
    return 0;
}
```

What integer is printed by the following C program?
```c
#include <stdio.h>
int main() {
    unsigned int a = 0x2D; /* 45 */
    unsigned int b = 0x1B; /* 27 */
    printf("%u", (a & b) + (a | b));
    return 0;
}
```

What is the output of the following C program?
```c
#include <stdio.h>
int f(int n) {
    static int k = 1;
    if (n >= 5) return n;
    n = n + k;
    k++;
    return f(n);
}
int main() {
    printf("%d", f(1));
    return 0;
}
```
